"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][27]={"university_physics_de:M27-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M27-L1 – Zeitabhängige Störungstheorie und Übergangsraten<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: stationäre Störungstheorie;\nM11: Zweiniveausysteme; M26: Operatoren. <a\nhref=\"index.html?course=university_physics&amp;module=M26&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die Übergangsamplitude erster Ordnung\nherleiten, Resonanz erkennen und die Grenzen der Störungsnäherung\ngegenüber der Rabi-Dynamik erläutern.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein zeitlich veränderliches elektromagnetisches Feld kann ein Atom\nzwischen diskreten Energieniveaus anregen. Die stationäre\nStörungstheorie erfasst solche Übergänge nicht: Eine explizite\nZeitabhängigkeit muss in der Zustandsentwicklung berücksichtigt werden.\nDie Frequenz des Antriebs und die Energiedifferenz bestimmen gemeinsam\ndie Resonanz.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Schreibe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo>+<\/mo><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">H(t)=H_0+V(t)<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">H_0|n\\rangle=E_n|n\\rangle<\/annotation><\/semantics><\/math>\nund entwickle im Wechselwirkungsbild den Zustand in den ungestörten\nEigenzuständen. In erster Ordnung erhält man für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>≠<\/mo><mi>i<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f\\neq i<\/annotation><\/semantics><\/math>\neine Zeitintegration des Störmatrixelements\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">V_{fi}(t)<\/annotation><\/semantics><\/math>,\ngewichtet mit der Bohrfrequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>E<\/mi><mi>f<\/mi><\/msub><mo>−<\/mo><msub><mi>E<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>ℏ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega_{fi}=(E_f-E_i)/\\hbar<\/annotation><\/semantics><\/math>.\nBei einem harmonischen Antrieb\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>ℏ<\/mi><mi mathvariant=\"normal\">Ω<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ω<\/mi><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">V_{fi}(t)=\\hbar\\Omega\\cos(\\omega t)<\/annotation><\/semantics><\/math>\nerzeugen die beiden Exponentialanteile Nenner proportional zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mo>±<\/mo><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega_{fi}\\pm\\omega<\/annotation><\/semantics><\/math>.\nNahe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><msub><mi>ω<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\omega=\\omega_{fi}<\/annotation><\/semantics><\/math>\ndominiert der langsam rotierende Term. Für lange Zeiten aufgelöste\nKontinua führt derselbe Ansatz unter zusätzlichen Annahmen zur Goldenen\nRegel; für ein isoliertes kohärentes Zweiniveausystem hingegen ist die\nRabi-Lösung angemessen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>c<\/mi><mi>f<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msubsup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>−<\/mi><mfrac><mi>i<\/mi><mi>ℏ<\/mi><\/mfrac><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><mspace width=\"-0.167em\"><\/mspace><msub><mi>V<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mi>′<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>e<\/mi><mrow><mi>i<\/mi><msub><mi>ω<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mi>t<\/mi><mi>′<\/mi><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><mi>′<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>P<\/mi><mi>f<\/mi><\/msub><mo>≃<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msubsup><mi>c<\/mi><mi>f<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msubsup><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">c_f^{(1)}(t)=-\\frac{i}{\\hbar}\\int_0^t\\!V_{fi}(t\\prime)e^{i\\omega_{fi}t\\prime}\\,\\mathrm dt\\prime,\\qquad P_f\\simeq |c_f^{(1)}|^2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für ein resonant getriebenes Zweiniveausystem mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>ℏ<\/mi><mi mathvariant=\"normal\">Ω<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ω<\/mi><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">V(t)=\\hbar\\Omega\\cos(\\omega t)\\,\\sigma_x<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><msub><mi>ω<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\omega=\\omega_0<\/annotation><\/semantics><\/math>\ngilt nach der rotierenden-Wellen-Näherung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>ℏ<\/mi><mi mathvariant=\"normal\">Ω<\/mi><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">H_{\\mathrm{eff}}=\\hbar\\Omega\\sigma_x/2<\/annotation><\/semantics><\/math>.\nDaraus folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Ω<\/mi><mi>t<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P_e(t)=\\sin^2(\\Omega t/2)<\/annotation><\/semantics><\/math>.\nMit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Ω<\/mi><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mo>⋅<\/mo><mn>1000<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Omega=2\\pi\\cdot1000\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">t=0{,}25\\,\\mathrm{ms}<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>π<\/mi><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_e=\\sin^2(\\pi/4)=0{,}5<\/annotation><\/semantics><\/math>.\nEine rein lineare Störungsentwicklung würde bei zu langen Zeiten\nunphysikalisch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>&gt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P&gt;1<\/annotation><\/semantics><\/math>\nvorhersagen; die Grafik zeigt die begrenzte Rabi-Oszillation.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_073_DE.svg\"\nalt=\"Resonanzprofil und zeitliche Rabi-Anregungswahrscheinlichkeit eines Zweiniveausystems.\" />\n<figcaption aria-hidden=\"true\">Resonanzprofil und zeitliche\nRabi-Anregungswahrscheinlichkeit eines Zweiniveausystems.<\/figcaption>\n<\/figure>\n<p><em>Resonanz und kohärente Population im Rabi-Modell.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Größe entscheidet über die Resonanz zwischen zwei\nNiveaus?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>e<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_e<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Ω<\/mi><mi>t<\/mi><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega t=\\pi<\/annotation><\/semantics><\/math>\nim resonanten Rabi-Modell.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf die Goldene Regel nicht ohne Weiteres auf ein einzelnes\ngeschlossenes Zweiniveausystem übertragen werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Die Antriebsfrequenz muss nahe der Bohrfrequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mrow><mi>f<\/mi><mi>i<\/mi><\/mrow><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>E<\/mi><mi>f<\/mi><\/msub><mo>−<\/mo><msub><mi>E<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>ℏ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega_{fi}=(E_f-E_i)/\\hbar<\/annotation><\/semantics><\/math>\nliegen.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_e=\\sin^2(\\pi/2)=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die Goldene Regel setzt unter anderem geeignete Kontinuumszustände\nund eine zeitliche Grobkörnung voraus; ein isoliertes Paar zeigt\nkohärente Oszillationen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die rotierende-Wellen-Näherung erfordert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Ω<\/mi><mo>≪<\/mo><msub><mi>ω<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Omega\\ll\\omega_0<\/annotation><\/semantics><\/math>\nund einen nahe resonanten Antrieb. Sehr kurze Pulse, große\nVerstimmungen, starke Felder und offene Systeme benötigen eine genauere\nDynamik. Übergangswahrscheinlichkeiten müssen normiert bleiben.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Zeitabhängige Störungen verknüpfen Frequenzspektrum und\nÜbergangswahrscheinlichkeit. Die folgende Lektion behandelt den\nentgegengesetzten Grenzfall einer langsam veränderlichen\nHamiltonfunktion. <a href=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-06-quantum-physics-iii-spring-2018/pages/lecture-notes/\">MIT OpenCourseWare – Quantum Physics III (2018) lecture notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel zu Störungen, Adiabatik und Streuung; Fachlicher Bezug zur Lektion: M27-L1 – Zeitabhängige Störungstheorie und Übergangsraten · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L1 – Zeitabhängige Störungstheorie und Übergangsraten · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M27-L2 – Adiabatisches Theorem und geometrische Berry-Phase<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: Eigenzustände und\nZeitentwicklung; M26: Differentialgeometrie. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Dynamische und geometrische Phase trennen\nsowie die Berry-Phase eines Spins entlang eines geschlossenen Wegs\nbestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Quantensystem kann seinen momentanen Eigenzustand näherungsweise\nbeibehalten, wenn äußere Parameter langsam genug variiert werden.\nTrotzdem gewinnt es nicht nur eine dynamische Phase aus der Energie,\nsondern auch eine Phase aus dem zurückgelegten Weg im Parameterraum.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für einen nicht entarteten, durch eine endliche Lücke vom Rest\ngetrennten Eigenzustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>λ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|n(\\lambda(t))\\rangle<\/annotation><\/semantics><\/math>\nliefert die adiabatische Näherung einen Phasenfaktor aus zwei Anteilen.\nDer dynamische Anteil integriert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E_n(t)<\/annotation><\/semantics><\/math>\nüber die Zeit; der geometrische Anteil ist das Wegintegral der\nBerry-Verbindung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">𝒜<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mi>i<\/mi><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>∇<\/mi><mi>λ<\/mi><\/msub><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal A_n=i\\langle n|\\nabla_{\\lambda}n\\rangle<\/annotation><\/semantics><\/math>.\nUnter einer lokalen Eichtransformation verändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">𝒜<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\mathcal A_n<\/annotation><\/semantics><\/math>,\ndie geschlossene Phasenänderung aber nur um ein ganzzahliges Vielfaches\nvon\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>.\nFür einen Spin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>\nim langsam umlaufenden Magnetfeld ist die geometrische Phase des zur\nFeldrichtung ausgerichteten Eigenzustands das negative halbe\nRaumwinkelmaß.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>γ<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msub><mo>∮<\/mo><mi>C<\/mi><\/msub><mi>i<\/mi><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>∇<\/mi><mi>λ<\/mi><\/msub><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>⋅<\/mo><mi mathvariant=\"normal\">d<\/mi><mi>λ<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>γ<\/mi><mo>+<\/mo><\/msub><mo>=<\/mo><mi>−<\/mi><mfrac><msub><mi mathvariant=\"normal\">Ω<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mn>2<\/mn><\/mfrac><mrow><mspace width=\"0.222em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mrow><mi mathvariant=\"normal\">mod<\/mi><mo>&#8289;<\/mo><\/mrow><mspace width=\"0.222em\"><\/mspace><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\gamma_n=\\oint_C i\\langle n|\\nabla_{\\lambda}n\\rangle\\cdot\\mathrm d\\lambda,\\qquad \\gamma_{+}=-\\frac{\\Omega_{\\mathrm{solid}}}{2}\\pmod{2\\pi}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Das Magnetfeld beschreibt einen Kegel mit konstantem Polarwinkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>60<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=60^\\circ<\/annotation><\/semantics><\/math>.\nDie Spitze des Richtungsvektors läuft einmal im Azimut herum und\nüberstreicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Ω<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega_{\\mathrm{solid}}=2\\pi(1-\\cos\\theta)=\\pi<\/annotation><\/semantics><\/math>.\nSomit ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>γ<\/mi><mo>+<\/mo><\/msub><mo>=<\/mo><mi>−<\/mi><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\gamma_+=-\\pi/2<\/annotation><\/semantics><\/math>\nmodulo\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>.\nDie dynamische Phase hängt zusätzlich von Umlaufdauer und Energien ab.\nDas Diagramm zeigt Weg und eingeschlossene Fläche auf der Einheitskugel\nin Projektion.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_003_DE.svg\"\nalt=\"Geschlossener Parameterweg eines Spins auf einer Kugel und eingeschlossener Raumwinkel.\" />\n<figcaption aria-hidden=\"true\">Geschlossener Parameterweg eines Spins\nauf einer Kugel und eingeschlossener Raumwinkel.<\/figcaption>\n<\/figure>\n<p><em>Die Berry-Phase eines Spins ist proportional zum orientierten\nRaumwinkel.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was ist die Voraussetzung für eine einfache nichtentartete\nadiabatische Näherung?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>γ<\/mi><mo>+<\/mo><\/msub><annotation encoding=\"application/x-tex\">\\gamma_+<\/annotation><\/semantics><\/math>\nfür einen geschlossenen Kreis mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>90<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=90^\\circ<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ist die Berry-Verbindung selbst eichinvariant?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Langsame Parameteränderung gegenüber den durch Energielücken\nbestimmten Zeitskalen und keine relevante Lückenschließung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Ω<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">l<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega_{\\mathrm{solid}}=2\\pi<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>γ<\/mi><mo>+<\/mo><\/msub><mo>=<\/mo><mi>−<\/mi><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\gamma_+=-\\pi<\/annotation><\/semantics><\/math>\nmodulo\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein; die geschlossene Berry-Phase ist modulo\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>\neichinvariant.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Bei Entartungen kann eine nichtabelsche holonomische Entwicklung\nauftreten. In der Nähe vermiedener Kreuzungen kann die adiabatische\nNäherung versagen. Das Vorzeichen der Spinphase setzt eine explizite\nEigenzustands- und Pfadorientierung voraus.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die geometrische Phase misst globale Information eines\nParameterschleifenwegs. Als Nächstes betrachten wir, wie\nRotationssymmetrie Quantenzustände in gekoppelte Drehimpulse gliedert.\n<a href=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-06-quantum-physics-iii-spring-2018/pages/lecture-notes/\">MIT OpenCourseWare – Quantum Physics III (2018) lecture notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel zu Störungen, Adiabatik und Streuung; Fachlicher Bezug zur Lektion: M27-L2 – Adiabatisches Theorem und geometrische Berry-Phase · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L2 – Adiabatisches Theorem und geometrische Berry-Phase · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M27-L3 – Drehimpulskopplung, Singulett und Triplett<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M11: Spin und Messung; M12:\nDrehimpulsalgebra und Tensorprodukte. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die Kopplung zweier Spin-1/2-Teilchen\nerklären und die vierdimensionalen Zustände nach Gesamtdrehimpuls\nordnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Zwei Spin-1/2-Systeme besitzen zusammen vier Basiszustände. Ihre\nProdukbasis ist für einzelne Messungen nützlich, die Basis des\nGesamtdrehimpulses jedoch für rotationssymmetrische Wechselwirkungen.\nDie beiden Beschreibungen sind durch Clebsch–Gordan-Koeffizienten\nverbunden.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Der Gesamtoperator lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝑱<\/mi><mo>=<\/mo><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>1<\/mn><\/msub><mo>+<\/mo><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf J=\\mathbf S_1+\\mathbf S_2<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><msub><mi>s<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s_1=s_2=1/2<\/annotation><\/semantics><\/math>\nergeben sich nach der Drehimpulksummationsregel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">j=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">j=1<\/annotation><\/semantics><\/math>.\nDie drei Triplettzustände besitzen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">j=1<\/annotation><\/semantics><\/math>,\nder einzelne Singulettzustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">j=0<\/annotation><\/semantics><\/math>.\nIm Unterraum mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=0<\/annotation><\/semantics><\/math>\nsind die normierten symmetrischen und antisymmetrischen Kombinationen\nentscheidend. Aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>J<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><msubsup><mi>J<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>J<\/mi><mn>2<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><mn>2<\/mn><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>1<\/mn><\/msub><mo>⋅<\/mo><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">J^2=J_1^2+J_2^2+2\\mathbf S_1\\cdot\\mathbf S_2<\/annotation><\/semantics><\/math>\nfolgen für das Skalarprodukt die Eigenwerte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\hbar^2/4<\/annotation><\/semantics><\/math>\n(Triplett) und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>3<\/mn><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-3\\hbar^2/4<\/annotation><\/semantics><\/math>\n(Singulett).<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>↑<\/mo><mo>↓<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>↓<\/mo><mo>↑<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><msqrt><mn>2<\/mn><\/msqrt><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>↑<\/mo><mo>↓<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>↓<\/mo><mo>↑<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><msqrt><mn>2<\/mn><\/msqrt><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|1,0\\rangle=\\frac{|\\uparrow\\downarrow\\rangle+|\\downarrow\\uparrow\\rangle}{\\sqrt2},\\qquad |0,0\\rangle=\\frac{|\\uparrow\\downarrow\\rangle-|\\downarrow\\uparrow\\rangle}{\\sqrt2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für die isotrope Austauschwechselwirkung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mo>=<\/mo><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>1<\/mn><\/msub><mo>⋅<\/mo><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>2<\/mn><\/msub><mi>/<\/mi><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">H=J_{\\mathrm{ex}}\\mathbf S_1\\cdot\\mathbf S_2/\\hbar^2<\/annotation><\/semantics><\/math>\nhat das Triplett die Energie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">J_{\\mathrm{ex}}/4<\/annotation><\/semantics><\/math>\nund das Singulett\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>3<\/mn><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-3J_{\\mathrm{ex}}/4<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">J_{\\mathrm{ex}}=4\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>\nbeträgt die Energiedifferenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">p<\/mi><\/mrow><\/msub><mo>−<\/mo><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E_{\\mathrm{trip}}-E_{\\mathrm{sing}}=4\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>.\nDas Energieniveauschema verdeutlicht die dreifache Entartung des\nTripletts ohne externes Feld.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_271_DE.svg\"\nalt=\"Energieniveaus eines Singulett- und eines dreifach entarteten Triplettzustands.\" />\n<figcaption aria-hidden=\"true\">Energieniveaus eines Singulett- und eines\ndreifach entarteten Triplettzustands.<\/figcaption>\n<\/figure>\n<p><em>Die Austauschkopplung spaltet den Gesamtdrehimpuls in Singulett\nund Triplett.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie viele gekoppelte Zustände besitzt das System aus zwei\nSpin-1/2-Teilchen insgesamt?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>1<\/mn><\/msub><mo>⋅<\/mo><msub><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\langle\\mathbf S_1\\cdot\\mathbf S_2\\rangle<\/annotation><\/semantics><\/math>\nfür das Singulett.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welcher Zustand ist für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">J_{\\mathrm{ex}}&gt;0<\/annotation><\/semantics><\/math>\nim angegebenen Modell energetisch tiefer?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Vier: ein Singulett und drei Triplettzustände.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>3<\/mn><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-3\\hbar^2/4<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Das Singulett mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>3<\/mn><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-3J_{\\mathrm{ex}}/4<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Austauschmodell ist isotrop und beschreibt hier zwei\nunterscheidbare Spin-Freiheitsgrade; für identische Teilchen muss\nzusätzlich die Symmetrie des gesamten Zustands einschließlich des\nOrtsanteils beachtet werden. Die Bezeichnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>J<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">J_{\\mathrm{ex}}<\/annotation><\/semantics><\/math>\nist keine Drehimpulsquantenzahl.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Rotationssymmetrie macht die gekoppelte Basis natürlich. Die folgende\nLektion löst sich von reinen Zustandsvektoren und führt Dichteoperatoren\nein. <a href=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L3 – Drehimpulskopplung, Singulett und Triplett · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/5-73-introductory-quantum-mechanics-i-fall-2005/pages/lecture-notes/\">Introductory Quantum Mechanics I – Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenindex zu Spin und Drehimpulskopplung; Fachlicher Bezug zur Lektion: M27-L3 – Drehimpulskopplung, Singulett und Triplett · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M27-L4 – Dichteoperatoren, gemischte Zustände und Dekohärenz<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M11: Messpostulate; M12:\nQuantenzeitentwicklung und Operatoren. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Dichtematrizen als Beschreibung\nstatistischer Ensembles verwenden, Reinheit berechnen und Phasenverlust\nvon Populationsrelaxation unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein reiner Zustandsvektor genügt nicht, wenn das\nPräparationsverfahren unsicher ist oder ein Teil eines verschränkten\nSystems betrachtet wird. Der Dichteoperator fasst statistische und\nquantenmechanische Wahrscheinlichkeiten konsistent zusammen; sein\nSpektrum und seine Nichtdiagonalelemente tragen unterschiedliche\nInformation.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für ein Ensemble\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>p<\/mi><mi>k<\/mi><\/msub><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ψ<\/mi><mi>k<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\{p_k,|\\psi_k\\rangle\\}<\/annotation><\/semantics><\/math>\ndefiniert man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><msub><mo>∑<\/mo><mi>k<\/mi><\/msub><msub><mi>p<\/mi><mi>k<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ψ<\/mi><mi>k<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msub><mi>ψ<\/mi><mi>k<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\rho=\\sum_k p_k|\\psi_k\\rangle\\langle\\psi_k|<\/annotation><\/semantics><\/math>.\nPhysikalische Dichtematrizen sind hermitesch, positiv semidefinit und\nspurnormiert. Messwerte folgen aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ρ<\/mi><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\langle A\\rangle=\\mathrm{tr}(\\rho A)<\/annotation><\/semantics><\/math>.\nFür einen Qubit-Zustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>+<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>+<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\rho(0)=|+\\rangle\\langle+|<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>+<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">|+\\rangle=(|0\\rangle+|1\\rangle)/\\sqrt2<\/annotation><\/semantics><\/math>\nsei nur reine Dephasierung wirksam: Die Populationen bleiben konstant,\nwährend\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ρ<\/mi><mn>01<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi mathvariant=\"normal\">Γ<\/mi><mi>t<\/mi><\/mrow><\/msup><msub><mi>ρ<\/mi><mn>01<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\rho_{01}(t)=e^{-\\Gamma t}\\rho_{01}(0)<\/annotation><\/semantics><\/math>.\nDie Reinheit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>ρ<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{tr}(\\rho^2)<\/annotation><\/semantics><\/math>\nmisst dann die Abnahme der Kohärenz.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi mathvariant=\"normal\">Γ<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi mathvariant=\"normal\">Γ<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mfrac><mrow><mn>1<\/mn><mo>+<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>2<\/mn><mi mathvariant=\"normal\">Γ<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><mn>2<\/mn><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\rho(t)=\\frac12\\begin{pmatrix}1&amp;e^{-\\Gamma t}\\\\e^{-\\Gamma t}&amp;1\\end{pmatrix},\\qquad \\mathrm{tr}[\\rho(t)^2]=\\frac{1+e^{-2\\Gamma t}}{2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mi>t<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma t=\\ln2<\/annotation><\/semantics><\/math>\nsind die Nebendiagonaleinträge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/4<\/annotation><\/semantics><\/math>\nstatt anfangs\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.\nDie Reinheit ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>5<\/mn><mi>/<\/mi><mn>8<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>625<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(1+1/4)/2=5/8=0{,}625<\/annotation><\/semantics><\/math>,\nwährend beide Populationswahrscheinlichkeiten weiterhin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>\nbetragen. Die Grafik trennt das abklingende Kohärenzmaß\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ρ<\/mi><mn>01<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">2|\\rho_{01}|<\/annotation><\/semantics><\/math>\nvon den konstanten Populationen. Eine fehlende Interferenz ist damit\nnicht dasselbe wie eine Änderung der Energiebesetzung.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_235_DE.svg\"\nalt=\"Zwei Kurven: unveränderte Zustandsbesetzung und exponentiell sinkende Qubit-Kohärenz.\" />\n<figcaption aria-hidden=\"true\">Zwei Kurven: unveränderte\nZustandsbesetzung und exponentiell sinkende Qubit-Kohärenz.<\/figcaption>\n<\/figure>\n<p><em>Reine Dephasierung reduziert Kohärenz, nicht die\nPopulationen.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche drei Bedingungen erfüllen physikalische Dichtematrizen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne die Reinheit für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>→<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t\\to\\infty<\/annotation><\/semantics><\/math>\nim Dephasierungsmodell.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ändert reine Dephasierung hier die Diagonalelemente?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Hermitizität, positive Semidefinitheit und Spur eins.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Reinheit nähert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein, die beiden Populationen bleiben\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das exponentielle Abklingen modelliert eine Markov- oder geeignete\nEffektivdynamik und gilt nicht für jede mikroskopische Umgebung. Eine\nreduzierte Dichtematrix kann gemischt sein, obwohl der Gesamtzustand\nrein ist. Reinheit ist allein kein universelles Verschränkungsmaß.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Dichtematrizen trennen Besetzung und Kohärenz. Im Folgenden wird\nuntersucht, wie Randbedingungen eine einfallende Quantenwelle in\nreflektierte und transmittierte Anteile zerlegen. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-06-quantum-physics-iii-spring-2016/download/\">MIT OpenCourseWare – Quantum Physics III (2016) resources<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitelübersicht zu Dichtematrizen und Dekohärenz; Fachlicher Bezug zur Lektion: M27-L4 – Dichteoperatoren, gemischte Zustände und Dekohärenz · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L4 – Dichteoperatoren, gemischte Zustände und Dekohärenz · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M27-L5 – Quantentheoretische Streuung und Streumatrix<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: eindimensionale\nSchrödingergleichung; M10: Wellen und Randbedingungen. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Reflexions- und Transmissionsamplituden\neiner Punktbarriere bestimmen und zwischen exakter Streuung und\nBorn-Näherung unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Auch eine räumlich stark lokalisierte Wechselwirkung kann eine\nausgedehnte Materiewelle reflektieren. Streuung verknüpft die\nasymptotischen ein- und auslaufenden Zustände; messbare\nWahrscheinlichkeiten werden aus Betragsquadraten der Amplituden\ngewonnen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Eine Teilchenwelle mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><msup><mi>k<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E=\\hbar^2k^2/(2m)<\/annotation><\/semantics><\/math>\ntrifft von links auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>g<\/mi><mi>δ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">V(x)=g\\delta(x)<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>&lt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x&lt;0<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ψ<\/mi><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>i<\/mi><mi>k<\/mi><mi>x<\/mi><\/mrow><\/msup><mo>+<\/mo><mi>r<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>i<\/mi><mi>k<\/mi><mi>x<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\psi=e^{ikx}+re^{-ikx}<\/annotation><\/semantics><\/math>,\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x&gt;0<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ψ<\/mi><mo>=<\/mo><mi>t<\/mi><msup><mi>e<\/mi><mrow><mi>i<\/mi><mi>k<\/mi><mi>x<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\psi=te^{ikx}<\/annotation><\/semantics><\/math>.\nDie Wellenfunktion ist stetig, doch ihre Ableitung hat wegen der\nPunktwechselwirkung den Sprung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>ψ<\/mi><mo>′<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mn>0<\/mn><mo>+<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msup><mi>ψ<\/mi><mo>′<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mn>0<\/mn><mo>−<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mi>m<\/mi><mi>g<\/mi><mi>ψ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\psi&#39;(0^+)-\\psi&#39;(0^-)=2mg\\psi(0)/\\hbar^2<\/annotation><\/semantics><\/math>.\nHieraus folgen die dimensionslosen Kopplung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α<\/mi><mo>=<\/mo><mi>m<\/mi><mi>g<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><mi>k<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\alpha=mg/(\\hbar^2k)<\/annotation><\/semantics><\/math>\nund die Amplituden\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><mi>α<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">t=1/(1+i\\alpha)<\/annotation><\/semantics><\/math>\nsowie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r<\/mi><mo>=<\/mo><mi>−<\/mi><mi>i<\/mi><mi>α<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><mi>α<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">r=-i\\alpha/(1+i\\alpha)<\/annotation><\/semantics><\/math>.\nGleiche asymptotische Geschwindigkeiten links und rechts sichern\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>+<\/mo><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T+R=1<\/annotation><\/semantics><\/math>.\nIn drei Dimensionen beschreibt die Streuamplitude\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo>,<\/mo><mi>φ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(\\theta,\\varphi)<\/annotation><\/semantics><\/math>\ndagegen einen differentiellen Wirkungsquerschnitt; die Born-Näherung ist\nnur für schwache Streuung zuverlässig.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mfrac><mn>1<\/mn><mrow><mn>1<\/mn><mo>+<\/mo><msup><mi>α<\/mi><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>R<\/mi><mo>=<\/mo><mfrac><msup><mi>α<\/mi><mn>2<\/mn><\/msup><mrow><mn>1<\/mn><mo>+<\/mo><msup><mi>α<\/mi><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>α<\/mi><mo>=<\/mo><mfrac><mrow><mi>m<\/mi><mi>g<\/mi><\/mrow><mrow><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><mi>k<\/mi><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>T<\/mi><mo>+<\/mo><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=\\frac{1}{1+\\alpha^2},\\qquad R=\\frac{\\alpha^2}{1+\\alpha^2},\\qquad \\alpha=\\frac{mg}{\\hbar^2k},\\qquad T+R=1.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Setze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\alpha=1<\/annotation><\/semantics><\/math>.\nDann ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>i<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=(1-i)/2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r<\/mi><mo>=<\/mo><mi>−<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>i<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">r=-(1+i)/2<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T=1/2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R=1/2<\/annotation><\/semantics><\/math>.\nDas Diagramm vergleicht die beiden Wahrscheinlichkeiten für verschieden\nstarke Kopplung. Die Summe bleibt stets eins, da das Modell keine\nAbsorption enthält.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_067_DE.svg\"\nalt=\"Transmissions- und Reflexionswahrscheinlichkeit an einer eindimensionalen Delta-Barriere als Funktion der Kopplung.\" />\n<figcaption aria-hidden=\"true\">Transmissions- und\nReflexionswahrscheinlichkeit an einer eindimensionalen Delta-Barriere\nals Funktion der Kopplung.<\/figcaption>\n<\/figure>\n<p><em>Exakte ein-kanalige Streuung erhält den\nGesamtwahrscheinlichkeitsstrom.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie lautet die Sprungbedingung für die Ableitung am\nDelta-Potential?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\alpha=2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum genügt im allgemeinen dreidimensionalen Fall nicht die\neindimensionale Größe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nzur Beschreibung eines Streuexperiments?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ψ<\/mi><mi>′<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mn>0<\/mn><mo>+<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>ψ<\/mi><mi>′<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mn>0<\/mn><mo>−<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mi>m<\/mi><mi>g<\/mi><mi>ψ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\psi\\prime(0^+)-\\psi\\prime(0^-)=2mg\\psi(0)/\\hbar^2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T=1/(1+4)=0{,}2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R=0{,}8<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Streufluss verteilt sich über Raumrichtungen; dafür wird etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">d<\/mi><mi>σ<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">Ω<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>f<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm d\\sigma/\\mathrm d\\Omega=|f|^2<\/annotation><\/semantics><\/math>\nverwendet.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Delta-Potential ist ein idealisiertes eindimensionales Modell mit\nwohldefinierter Sprungbedingung. Die Übertragung auf reale\ndreidimensionale Streuer verlangt Regularisierung, geeignete\nRandbedingungen und ggf. Mehrkanalstreuung. Eine unitarische Streumatrix\nsetzt fehlende Verlustkanäle voraus.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Streuwahrscheinlichkeiten folgen aus korrekten asymptotischen\nRandbedingungen und Stromerhaltung. Die nächste Lektion verbindet das\nquantenmechanische Energiespektrum mit der speziellen\nRelativitätstheorie. <a href=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-06-quantum-physics-iii-spring-2018/pages/lecture-notes/\">MIT OpenCourseWare – Quantum Physics III (2018) lecture notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel zu Störungen, Adiabatik und Streuung; Fachlicher Bezug zur Lektion: M27-L5 – Quantentheoretische Streuung und Streumatrix · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L5 – Quantentheoretische Streuung und Streumatrix · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M27-L6 – Relativistische Quantenmechanik und Dirac-Gleichung<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M10: Relativität und\nElektrodynamik; M12: Operatoren und Wellenfunktionen. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die relativistische Dispersionsrelation\nherleiten und die Rolle der antikommutierenden Dirac-Matrizen bei einer\nlinearen Hamiltonfunktion erklären.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Die nichtrelativistische Schrödingergleichung enthält eine\nquadratische Impulsenergie. Spezielle Relativität verlangt dagegen eine\nEnergie-Impuls-Beziehung mit Ruheenergie. Der Dirac-Ansatz linearisiert\ndie relativistische Beziehung, führt aber zu einer mehrkomponentigen\nWellenfunktion.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Aus dem Viererimpuls folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>E<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><msup><mi>p<\/mi><mn>2<\/mn><\/msup><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>m<\/mi><mn>2<\/mn><\/msup><msup><mi>c<\/mi><mn>4<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">E^2=p^2c^2+m^2c^4<\/annotation><\/semantics><\/math>.\nEine Hamiltonfunktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mi>D<\/mi><\/msub><mo>=<\/mo><mi>c<\/mi><mi mathvariant=\"bold-italic\">𝜶<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝒑<\/mi><mo>+<\/mo><mi>β<\/mi><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">H_D=c\\boldsymbol\\alpha\\cdot\\mathbf p+\\beta mc^2<\/annotation><\/semantics><\/math>\nerfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>H<\/mi><mi>D<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><msup><mi>E<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">H_D^2=E^2<\/annotation><\/semantics><\/math>\nals Operatorgleichung, wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>α<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><msub><mi>α<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>2<\/mn><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\{\\alpha_i,\\alpha_j\\}=2\\delta_{ij}I<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>α<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><mi>β<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\{\\alpha_i,\\beta\\}=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>β<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\beta^2=I<\/annotation><\/semantics><\/math>.\nDeshalb sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>α<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\alpha_i<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>β<\/mi><annotation encoding=\"application/x-tex\">\\beta<\/annotation><\/semantics><\/math>\nMatrizen und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ψ<\/mi><annotation encoding=\"application/x-tex\">\\psi<\/annotation><\/semantics><\/math>\nein Spinor. In der positiven Energieverzweigung liefert die Entwicklung\nfür kleine Impulse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>≃<\/mo><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msup><mi>p<\/mi><mn>4<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>8<\/mn><msup><mi>m<\/mi><mn>3<\/mn><\/msup><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>⋯<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E\\simeq mc^2+p^2/(2m)-p^4/(8m^3c^2)+\\cdots<\/annotation><\/semantics><\/math>.\nDie Theorie enthält zusätzlich Lösungen mit negativer Energie, deren\nkonsistente Interpretation in der Quantenelektrodynamik erfolgt.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mi>D<\/mi><\/msub><mo>=<\/mo><mi>c<\/mi><mi mathvariant=\"bold-italic\">𝜶<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝒑<\/mi><mo>+<\/mo><mi>β<\/mi><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msubsup><mi>H<\/mi><mi>D<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>p<\/mi><mn>2<\/mn><\/msup><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>m<\/mi><mn>2<\/mn><\/msup><msup><mi>c<\/mi><mn>4<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>I<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">H_D=c\\boldsymbol\\alpha\\cdot\\mathbf p+\\beta mc^2,\\qquad H_D^2=(p^2c^2+m^2c^4)I.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für ein Elektron mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0<\/annotation><\/semantics><\/math>\nbeträgt die positive Energie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>511<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">mc^2\\approx0{,}511\\,\\mathrm{MeV}<\/annotation><\/semantics><\/math>.\nIst\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mi>c<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">pc=0{,}3mc^2<\/annotation><\/semantics><\/math>,\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><msqrt><mrow><mn>1<\/mn><mo>+<\/mo><mn>0<\/mn><mo>,<\/mo><msup><mn>3<\/mn><mn>2<\/mn><\/msup><\/mrow><\/msqrt><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0440<\/mn><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">E=mc^2\\sqrt{1+0{,}3^2}\\approx1{,}0440mc^2<\/annotation><\/semantics><\/math>.\nDie Zunahme gegenüber der Ruheenergie ist damit rund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>0440<\/mn><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">0{,}0440mc^2<\/annotation><\/semantics><\/math>,\nwährend der nichtrelativistische Näherungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>045<\/mn><mi>m<\/mi><msup><mi>c<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">p^2/(2m)=0{,}045mc^2<\/annotation><\/semantics><\/math>\nliefert. Die Grafik vergleicht beide kinetischen Energien als Funktion\nvon\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>m<\/mi><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">p/(mc)<\/annotation><\/semantics><\/math>.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_072_DE.svg\"\nalt=\"Vergleich der relativistischen und nichtrelativistischen kinetischen Energie bei zunehmendem Impuls.\" />\n<figcaption aria-hidden=\"true\">Vergleich der relativistischen und\nnichtrelativistischen kinetischen Energie bei zunehmendem\nImpuls.<\/figcaption>\n<\/figure>\n<p><em>Relativistische und quadratische Näherung der kinetischen Energie\nals Funktion des Impulses.<\/em><\/p>\n<p>Die beiden Näherungen stimmen nur bei kleinen Impulsen überein.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Matrizenrelation verhindert unerwünschte gemischte Terme in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msubsup><mi>H<\/mi><mi>D<\/mi><mn>2<\/mn><\/msubsup><annotation encoding=\"application/x-tex\">H_D^2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Ruheenergie besitzt ein Elektron näherungsweise?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ab welchem Regime wird\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">p^2/(2m)<\/annotation><\/semantics><\/math>\nals kinetische Energie unzureichend?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Insbesondere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>α<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><mi>β<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\{\\alpha_i,\\beta\\}=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>α<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><msub><mi>α<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>2<\/mn><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\{\\alpha_i,\\alpha_j\\}=2\\delta_{ij}I<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Ungefähr\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>511<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}511\\,\\mathrm{MeV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Bei Impulsen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nin der Größenordnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">mc<\/annotation><\/semantics><\/math>\noder darüber sind relativistische Korrekturen groß.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der Einteilchen-Dirac-Ansatz erklärt nicht alle Mehrteilchen- und\nTeilchenerzeugungsprozesse. Für konsistente Wechselwirkungen mit\nPaarerzeugung ist Quantenfeldtheorie nötig. Negative Energiezweige\ndürfen nicht naiv als stabile, unbegrenzt besetzbare Einteilchenzustände\ninterpretiert werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Dirac-Matrizen kodieren relativistische Dispersion und Spin. Als\nNächstes berücksichtigen wir, dass ein Quantensystem durch den Kontakt\nmit einer Umgebung nichtunitär relaxieren kann. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L6 – Relativistische Quantenmechanik und Dirac-Gleichung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M27-L7 – Offene Quantensysteme und Lindblad-Gleichung<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M27-L4: Dichteoperator; M13:\nstatistische Ensembles. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die GKSL-Form mit einheitlicher\nRatenkonvention anwenden und den Unterschied zwischen Populationszerfall\nund Kohärenzzerfall berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein System tauscht mit seiner Umgebung Energie und Information aus.\nNach Ausspuren der Umgebungsfreiheitsgrade entwickelt sich sein\nDichteoperator häufig nicht mehr unitär. Ein zeitlich homogener,\nmarkovscher und vollständig positiver Dynamikgenerator kann unter\nüblichen endlichdimensionalen Voraussetzungen in Lindblad-Form\ngeschrieben werden.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für einen dimensionslosen Sprungoperator\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>\nund eine nichtnegative Rate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nbesitzt der Dissipator die Form\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>γ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>L<\/mi><mi>ρ<\/mi><msup><mi>L<\/mi><mo>†<\/mo><\/msup><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msup><mi>L<\/mi><mo>†<\/mo><\/msup><mi>L<\/mi><mo>,<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\gamma(L\\rho L^\\dagger-\\{L^\\dagger L,\\rho\\}/2)<\/annotation><\/semantics><\/math>.\nWir wählen als Beispiel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>g<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>e<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">L=|g\\rangle\\langle e|<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">H=0<\/annotation><\/semantics><\/math>\n(oder das Wechselwirkungsbild eines diagonalen Hamiltonoperators). Dann\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>ρ<\/mi><mo accent=\"true\">̇<\/mo><\/mover><mrow><mi>e<\/mi><mi>e<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mi>γ<\/mi><msub><mi>ρ<\/mi><mrow><mi>e<\/mi><mi>e<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\dot\\rho_{ee}=-\\gamma\\rho_{ee}<\/annotation><\/semantics><\/math>,\nwährend\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>ρ<\/mi><mo accent=\"true\">̇<\/mo><\/mover><mrow><mi>e<\/mi><mi>g<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mi>γ<\/mi><msub><mi>ρ<\/mi><mrow><mi>e<\/mi><mi>g<\/mi><\/mrow><\/msub><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\dot\\rho_{eg}=-\\gamma\\rho_{eg}/2<\/annotation><\/semantics><\/math>\nist. Daher nimmt die angeregte Population mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>γ<\/mi><mi>t<\/mi><\/mrow><\/msup><annotation encoding=\"application/x-tex\">e^{-\\gamma t}<\/annotation><\/semantics><\/math>\nab und eine anfängliche Kohärenz mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>γ<\/mi><mi>t<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">e^{-\\gamma t/2}<\/annotation><\/semantics><\/math>.\nIn einer alternativen Notation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>→<\/mo><msqrt><mi>γ<\/mi><\/msqrt><mi>L<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L\\to\\sqrt\\gamma L<\/annotation><\/semantics><\/math>\nmuss der äußere Ratenfaktor wegfallen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>ρ<\/mi><mo accent=\"true\">̇<\/mo><\/mover><mo>=<\/mo><mi>−<\/mi><mfrac><mi>i<\/mi><mi>ℏ<\/mi><\/mfrac><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>H<\/mi><mo>,<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>+<\/mo><mi>γ<\/mi><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi>L<\/mi><mi>ρ<\/mi><msup><mi>L<\/mi><mo>†<\/mo><\/msup><mo>−<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msup><mi>L<\/mi><mo>†<\/mo><\/msup><mi>L<\/mi><mo>,<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>L<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>g<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>e<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\dot\\rho=-\\frac{i}{\\hbar}[H,\\rho]+\\gamma\\left(L\\rho L^\\dagger-\\tfrac12\\{L^\\dagger L,\\rho\\}\\right),\\qquad L=|g\\rangle\\langle e|.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für den Anfangszustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>e<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|e\\rangle<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>γ<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\gamma=2\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>\ngilt zur Zeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>γ<\/mi><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>347<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t=(\\ln2)/\\gamma\\approx0{,}347\\,\\mathrm s<\/annotation><\/semantics><\/math>\ndie angeregte Population\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ρ<\/mi><mrow><mi>e<\/mi><mi>e<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho_{ee}=1/2<\/annotation><\/semantics><\/math>\nund die Grundzustandspopulation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.\nFür anfängliche Kohärenz wäre ihr Betragsfaktor zu derselben Zeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>γ<\/mi><mi>t<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>707<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e^{-\\gamma t/2}=1/\\sqrt2\\approx0{,}707<\/annotation><\/semantics><\/math>.\nDas Diagramm zeigt beide Zerfallsraten. Eine reine Emission erzeugt aus\ndem zunächst rein angeregten Zustand keine Kohärenz.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_153_DE.svg\"\nalt=\"Abfall der angeregten Zustandsbesetzung und langsamerer Abfall einer Kohärenzamplitude unter Lindblad-Dynamik.\" />\n<figcaption aria-hidden=\"true\">Abfall der angeregten Zustandsbesetzung\nund langsamerer Abfall einer Kohärenzamplitude unter\nLindblad-Dynamik.<\/figcaption>\n<\/figure>\n<p><em>Für reine Amplitudendämpfung zerfällt Kohärenz mit halber\nPopulationsrate.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Eigenschaften muss die Rate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nin der gewählten GKSL-Form besitzen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>ρ<\/mi><mrow><mi>e<\/mi><mi>e<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">\\rho_{ee}<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>γ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\gamma t=1<\/annotation><\/semantics><\/math>\nfür anfänglich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ρ<\/mi><mrow><mi>e<\/mi><mi>e<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho_{ee}(0)=1<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wie ändert sich die Gleichung, falls\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msqrt><mi>γ<\/mi><\/msqrt><annotation encoding=\"application/x-tex\">\\sqrt\\gamma<\/annotation><\/semantics><\/math>\nbereits in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>\nenthalten ist?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>γ<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\gamma\\ge0<\/annotation><\/semantics><\/math>\nund Dimension\nZeit<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi><\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">^{-1}<\/annotation><\/semantics><\/math>,\nbei dimensionslosem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>368<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e^{-1}\\approx0{,}368<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der explizite Vorfaktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>γ<\/mi><annotation encoding=\"application/x-tex\">\\gamma<\/annotation><\/semantics><\/math>\nvor dem Dissipator entfällt.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die zeitunabhängige GKSL-Form setzt eine geeignete Markov- und\nHalbgruppenbeschreibung voraus. Nichtmarkovsche Gedächtniseffekte,\nstarke System-Bad-Kopplung und zeitabhängige Raten benötigen andere\nModellierungen. Der Sprungoperator repräsentiert nicht ohne zusätzliche\nMessmodellannahmen ein tatsächlich beobachtetes Ereignis.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Vollständig positive offene Dynamik trennt Kohärenz- und\nPopulationszerfall und erzwingt konsistente Ratenkonventionen. Das\nfolgende Kapitel hebt den Formalismus auf Räume mit variabler\nTeilchenzahl. <a href=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L8&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a><\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://interactivetextbooks.tudelft.nl/qsm/src/8_lindblad.html\">TU Delft – Lecture 8: The Lindblad Master Equation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · GKSL-Generator, normierte Sprungoperatoren und Zerfallsraten; Fachlicher Bezug zur Lektion: M27-L7 – Offene Quantensysteme und Lindblad-Gleichung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-06-quantum-physics-iii-spring-2016/download/\">MIT OpenCourseWare – Quantum Physics III (2016) resources<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitelübersicht zu Dichtematrizen und Dekohärenz; Fachlicher Bezug zur Lektion: M27-L7 – Offene Quantensysteme und Lindblad-Gleichung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M27-L8":"<article class=\"lesson-standard\"><h1 id=\"L8\">M27-L8 – Identische Teilchen und zweite Quantisierung<\/h1>\n<p><strong>Kursbereich:<\/strong> M27 – Master: Fortgeschrittene Quantentheorie<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M13: Fermi- und Bose-Statistik;\nM27-L3: Spin; M26: Operatoralgebra. <a\nhref=\"index.html?course=university_physics&amp;module=M27&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Fock-Zustände konstruieren,\nBesetzungszahlen für Bosonen und Fermionen unterscheiden und einen\nEinteilchen-Hamiltonoperator in zweiter Quantisierung schreiben.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Bei identischen Quantenteilchen ist eine Nummerierung einzelner\nTeilchen häufig unphysikalisch. Die zweite Quantisierung beschreibt\nstattdessen Besetzungen von Einteilchenmoden. Sie ist damit der\nnatürliche Ausgangspunkt der Vielteilchenphysik und der\nQuantenfeldtheorie.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Zu einer Mode\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>i<\/mi><annotation encoding=\"application/x-tex\">i<\/annotation><\/semantics><\/math>\ngehören Erzeugungs- und Vernichtungsoperatoren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><annotation encoding=\"application/x-tex\">a_i^\\dagger<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>a<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">a_i<\/annotation><\/semantics><\/math>.\nFür Bosonen gelten kanonische Kommutatoren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>a<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><msubsup><mi>a<\/mi><mi>j<\/mi><mo>†<\/mo><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">[a_i,a_j^\\dagger]=\\delta_{ij}<\/annotation><\/semantics><\/math>;\nfür Fermionen Antikommutatoren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>a<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><msubsup><mi>a<\/mi><mi>j<\/mi><mo>†<\/mo><\/msubsup><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\{a_i,a_j^\\dagger\\}=\\delta_{ij}<\/annotation><\/semantics><\/math>\nsowie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><mo>,<\/mo><msubsup><mi>a<\/mi><mi>j<\/mi><mo>†<\/mo><\/msubsup><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\{a_i^\\dagger,a_j^\\dagger\\}=0<\/annotation><\/semantics><\/math>.\nDer Zahloperator ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><msub><mi>a<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">n_i=a_i^\\dagger a_i<\/annotation><\/semantics><\/math>.\nEin nichtwechselwirkendes System mit Modenenergien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>ε<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\varepsilon_i<\/annotation><\/semantics><\/math>\nhat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><msub><mi>ε<\/mi><mi>i<\/mi><\/msub><msub><mi>n<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">H_0=\\sum_i\\varepsilon_i n_i<\/annotation><\/semantics><\/math>.\nFür Fermionen folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(a_i^\\dagger)^2=0<\/annotation><\/semantics><\/math>\nund die Besetzung einer einzelnen Mode ist 0 oder 1; Bosonen besitzen im\nPrinzip beliebige natürliche Besetzungszahlen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><munder><mo>∑<\/mo><mi>i<\/mi><\/munder><msub><mi>ε<\/mi><mi>i<\/mi><\/msub><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><msub><mi>a<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>a<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><msubsup><mi>a<\/mi><mi>j<\/mi><mo>†<\/mo><\/msubsup><msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi mathvariant=\"normal\">B<\/mi><\/msub><mo>=<\/mo><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>a<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><msubsup><mi>a<\/mi><mi>j<\/mi><mo>†<\/mo><\/msubsup><msub><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mi mathvariant=\"normal\">F<\/mi><\/msub><mo>=<\/mo><msub><mi>δ<\/mi><mrow><mi>i<\/mi><mi>j<\/mi><\/mrow><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">H_0=\\sum_i\\varepsilon_i a_i^\\dagger a_i,\\qquad [a_i,a_j^\\dagger]_{\\mathrm B}=\\delta_{ij},\\qquad \\{a_i,a_j^\\dagger\\}_{\\mathrm F}=\\delta_{ij}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Zwei verschiedene fermionische Moden besitzen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_1=1\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_2=2\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.\nDer Zustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>a<\/mi><mn>1<\/mn><mo>†<\/mo><\/msubsup><msubsup><mi>a<\/mi><mn>2<\/mn><mo>†<\/mo><\/msubsup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">a_1^\\dagger a_2^\\dagger|0\\rangle<\/annotation><\/semantics><\/math>\nträgt Gesamtenergie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">3\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.\nVertauscht man die Erzeugungsoperatoren, kehrt sich das Vorzeichen des\nZustands um; ein physikalischer Zustand ist jedoch nicht durch die\nReihenfolge der Namensetiketten charakterisiert. Die Grafik stellt\nerlaubte Besetzungen fermionischer und bosonischer Moden gegenüber.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_102_DE.svg\"\nalt=\"Vergleich möglicher Besetzungszahlen einer fermionischen und einer bosonischen Einzelmode.\" />\n<figcaption aria-hidden=\"true\">Vergleich möglicher Besetzungszahlen\neiner fermionischen und einer bosonischen Einzelmode.<\/figcaption>\n<\/figure>\n<p><em>Fermionen und Bosonen unterscheiden sich in den erlaubten\nModenbesetzungen.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Besetzungen sind in einer einzelnen fermionischen Mode\nmöglich?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne die Energie des zweifach besetzten Zustands zweier\ngetrennter Moden mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_1=1\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_2=2\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(a_i^\\dagger)^2<\/annotation><\/semantics><\/math>\nfür Fermionen null?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>i<\/mi><\/msub><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">n_i\\in\\{0,1\\}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><msub><mi>ε<\/mi><mn>1<\/mn><\/msub><mo>+<\/mo><msub><mi>ε<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E=\\varepsilon_1+\\varepsilon_2=3\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><mo>,<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\{a_i^\\dagger,a_i^\\dagger\\}=0<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>a<\/mi><mi>i<\/mi><mo>†<\/mo><\/msubsup><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2(a_i^\\dagger)^2=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Modenbasis muss vollständig und orthonormal oder entsprechend\ngeneralisiert sein. Wechselwirkungen fügen Terme mit mehreren\nErzeugungs- und Vernichtungsoperatoren hinzu. Die Symmetrie des\nGesamtzustands und die gewählte Teilchensorte bestimmen die\nOperatoralgebra.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die zweite Quantisierung schafft die Sprache der Mehrteilchensysteme.\nSie bildet den Übergang zum folgenden Modul über Nichtgleichgewichts-\nund Vielteilchenphysik.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-322-quantum-theory-ii-spring-2003/\">MIT OpenCourseWare – Quantum Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themenbeleg für vertiefte Quantentheorie; Fachlicher Bezug zur Lektion: M27-L8 – Identische Teilchen und zweite Quantisierung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-513-many-body-theory-for-condensed-matter-systems-fall-2004/pages/lecture-notes/\">MIT OpenCourseWare – Many-Body Theory for Condensed Matter Systems<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Vorlesungsverzeichnis zu zweiter Quantisierung und Vielteilchensystemen; Fachlicher Bezug zur Lektion: M27-L8 – Identische Teilchen und zweite Quantisierung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www2.physik.lmu.de/lehre/vorlesungen/sose_20/TVI_TMP-TA3/index.html\">LMU München – Condensed Matter Many-Body Physics and Field Theory I<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Lehrplan zu zweiter Quantisierung und Green-Funktionen; Fachlicher Bezug zur Lektion: M27-L8 – Identische Teilchen und zweite Quantisierung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
